//! 🧪️ Actual original Reserved bodies share neutral bytes, one-unit work and paid source closure.
use super::*;
use std::mem::size_of;
use semio_framework_plugin_testing_laws::OriginalWorkFixture;
use crate::{BoundedJob,JobStep};
use semio_framework_job::{OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::RetainedCloneStep;
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:128}}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128}}
fn caller()->OriginalWorkFixture{OriginalWorkFixture::with_source(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),stock(),||Some(1),1000000,100000)}
fn difference(after:RetainedCloneProgress,before:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes}}
fn birth(owner:&mut OriginalWorkFixture,input:Vec<u8>)->Box<FrameworkReservedBoundedJob>{let mut output=None;owner.work_turn(grant(),1,|cx|{let binding=semio_framework_job::OriginalSourceBinding::borrow(cx);admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:0,capacity_bytes:size_of::<FrameworkReservedBoundedJob>(),release_bytes:0,depth:1},|_|Ok((Box::new(FrameworkReservedBoundedJob::new(input,None,binding)),RetainedCloneProgress{copied_items:1,retained_capacity_bytes:size_of::<FrameworkReservedBoundedJob>(),..Default::default()})))?;Ok(())}).unwrap();output.unwrap()}
fn close_body(owner:&mut OriginalWorkFixture,body:&mut Option<Box<FrameworkReservedBoundedJob>>){
 for _ in 0..10000{if body.as_ref().unwrap().terminal_drop_is_shallow(){break}let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();body.as_mut().unwrap().close_step(cx)?;Ok(difference(cx.retained_progress(),before))})).unwrap());assert!(progress.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}
 assert!(body.as_ref().unwrap().terminal_drop_is_shallow());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,RetirementDemand{release_bytes:size_of::<FrameworkReservedBoundedJob>(),depth:1,..Default::default()},|_|{drop(body.take());Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:size_of::<FrameworkReservedBoundedJob>(),..Default::default()}))})?;Ok(())})).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,size_of::<FrameworkReservedBoundedJob>()));
}
fn close_output(owner:&mut OriginalWorkFixture,output:&mut Option<Vec<u8>>){let mut closing=None;for _ in 0..10000{if owner.work_turn(grant(),1,|cx|super::super::close_original(output,&mut closing,cx)).unwrap(){return}}panic!("original output close must finish")}
#[test]
fn reserved_registry_original_body_bytes_and_actual_receipts_share_one_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let input:Vec<u8>=serde_json::from_value(row["input"].clone()).unwrap();let expected:Vec<u8>=serde_json::from_value(row["output"].clone()).unwrap();let mut owner=caller();let mut body=Some(birth(&mut owner,input));let mut output=None;
  let mut foreign=caller();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.work_turn(grant(),1,|cx|body.as_mut().unwrap().step_original(cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));foreign.finish();
  for _ in 0..10000{let((step,progress,spent),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let step=body.as_mut().unwrap().step_original(cx)?;Ok((step,difference(cx.retained_progress(),before),fuel-cx.fuel_remaining()))}).unwrap());assert!(progress.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if progress!=Default::default(){assert_eq!(spent,1)}match step{JobStep::Running(None)=>{},JobStep::Done(bytes)=>{output=Some(bytes);break},_=>panic!("original reserved body produced unrelated output")}}
  assert_eq!(output.as_ref().unwrap(),&expected);assert!(body.as_ref().unwrap().terminal_drop_is_shallow());close_body(&mut owner,&mut body);close_output(&mut owner,&mut output);owner.finish();
 }
}
#[test]
fn reserved_registry_original_body_work_denials_preserve_input_and_last_unit_progress(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in law["work"].as_array().unwrap(){let mut owner=caller();let mut body=Some(birth(&mut owner,vec![97,98,99]));let pointer=body.as_ref().unwrap().source.as_ref().unwrap().0.as_ptr();if row["cancelled"].as_bool().unwrap(){owner.cancel().cancel_now();}let policy=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,..grant()};let((advanced,remaining),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(policy,row["fuel"].as_u64().unwrap(),|cx|{if row["expired"].as_bool().unwrap(){cx.narrow_original_work_budget(semio_framework_job::StepBudget::new(cx.fuel_remaining(),0,cx.retained_grant()))?;}let before=cx.retained_progress();assert!(matches!(body.as_mut().unwrap().step_original(cx)?,JobStep::Running(None)));Ok((cx.retained_progress()!=before,cx.fuel_remaining()))}).unwrap());assert_eq!(advanced,row["advanced"].as_bool().unwrap());assert_eq!(remaining,row["remainingFuel"].as_u64().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(pointer,body.as_ref().unwrap().source.as_ref().unwrap().0.as_ptr());close_body(&mut owner,&mut body);owner.finish();}
}

#[test]
fn reserved_registry_original_partial_output_cancel_keeps_backings_until_same_source_close(){
 let mut owner=caller();let mut body=Some(birth(&mut owner,vec![81;65]));for _ in 0..100{if body.as_ref().unwrap().phase==2{break}owner.work_turn(grant(),1,|cx|body.as_mut().unwrap().step_original(cx)).unwrap();}assert_eq!(body.as_ref().unwrap().phase,2);
 owner.work_turn(RetainedCloneGrant{maximum_copy_bytes:3,..grant()},1,|cx|body.as_mut().unwrap().step_original(cx)).unwrap();assert_eq!(body.as_ref().unwrap().output.as_ref().unwrap().len(),3);let source=body.as_ref().unwrap().source.as_ref().unwrap().0.as_ptr();let output=body.as_ref().unwrap().output.as_ref().unwrap().as_ptr();owner.cancel().cancel_now();
 let((progress,remaining),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|{let before=cx.retained_progress();assert!(matches!(body.as_mut().unwrap().step_original(cx)?,JobStep::Running(None)));Ok((difference(cx.retained_progress(),before),cx.fuel_remaining()))}).unwrap());assert_eq!(progress,Default::default());assert_eq!(remaining,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(source,body.as_ref().unwrap().source.as_ref().unwrap().0.as_ptr());assert_eq!(output,body.as_ref().unwrap().output.as_ref().unwrap().as_ptr());close_body(&mut owner,&mut body);owner.finish();
}

std::thread_local!{static RESERVED_CLOCK:std::cell::Cell<u64>=const{std::cell::Cell::new(1)};}
fn reserved_now()->Option<u64>{Some(RESERVED_CLOCK.with(std::cell::Cell::get))}
#[test]
fn reserved_registry_original_expired_clock_closes_partial_output_without_renewal(){
 RESERVED_CLOCK.with(|clock|clock.set(1));let mut owner=OriginalWorkFixture::with_source(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),stock(),reserved_now,100,100000);let mut body=Some(birth(&mut owner,vec![81;65]));
 for _ in 0..100{if body.as_ref().unwrap().phase==2{break}owner.work_turn(grant(),1,|cx|body.as_mut().unwrap().step_original(cx)).unwrap();}assert_eq!(body.as_ref().unwrap().phase,2);owner.work_turn(RetainedCloneGrant{maximum_copy_bytes:3,..grant()},1,|cx|body.as_mut().unwrap().step_original(cx)).unwrap();assert_eq!(body.as_ref().unwrap().output.as_ref().unwrap().len(),3);
 RESERVED_CLOCK.with(|clock|clock.set(101));let((before,after),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|{assert!(cx.should_yield());let before=cx.retained_progress();assert!(matches!(body.as_mut().unwrap().step_original(cx)?,JobStep::Running(None)));assert!(!body.as_mut().unwrap().close_step(cx)?);Ok((before,cx.retained_progress()))}).unwrap());assert_eq!(before,after);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 for(fuel,items)in[(0,1),(1,0)]{let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(RetainedCloneGrant{maximum_items:items,..grant()},fuel,|cx|cx.with_original_retirement(|cx|{assert!(cx.should_yield());let before=cx.retained_progress();assert!(!body.as_mut().unwrap().close_step(cx)?);Ok(difference(cx.retained_progress(),before))})).unwrap());assert_eq!(progress,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 close_body(&mut owner,&mut body);assert_eq!(reserved_now(),Some(101));owner.finish();assert_eq!(reserved_now(),Some(101));
}

#[test]
fn reserved_registry_original_expired_clock_closes_failed_and_bounded_slot_owners(){
 for failed in[false,true]{RESERVED_CLOCK.with(|clock|clock.set(1));let mut owner=OriginalWorkFixture::with_source(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),stock(),reserved_now,100,100000);let original=birth(&mut owner,vec![81;65]);let binding=original.binding;let original:Box<dyn BoundedJob>=original;let(body,failed_owner)=if failed{(None,Some(original))}else{(Some(super::super::JobBody::Bounded(original)),None)};
  let mut slot=super::super::JobSlot{binding,job:71,identity:(71,3),source:None,source_close:None,body,failed_owner,outcome:None,outcome_close:None,rejected_output:None,rejected_output_close:None,cancelled:false,cancellation_fault_started:false,cancellation_signalled:false};RESERVED_CLOCK.with(|clock|clock.set(101));
  let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|{let before=cx.retained_progress();assert!(!if failed{super::super::close_failed_owner(&mut slot,cx)?}else{super::super::close_body(&mut slot,cx)?});Ok(difference(cx.retained_progress(),before))}).unwrap());assert_eq!(progress,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for _ in 0..10000{if slot.body.is_none()&&slot.failed_owner.is_none(){break}let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|cx.with_original_retirement(|cx|{assert!(cx.should_yield());let before=cx.retained_progress();if failed{super::super::close_failed_owner(&mut slot,cx)?;}else{super::super::close_body(&mut slot,cx)?;}Ok(difference(cx.retained_progress(),before))})).unwrap());assert!(progress.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}
  assert!(slot.body.is_none()&&slot.failed_owner.is_none());assert_eq!(reserved_now(),Some(101));owner.finish();assert_eq!(reserved_now(),Some(101));
 }
}

#[test]
fn reserved_registry_original_global_close_rejects_foreign_source_and_keeps_expired_clock(){
 use semio_framework_actor::OriginalActorJobProvider;
 RESERVED_CLOCK.with(|clock|clock.set(1));let mut owner=OriginalWorkFixture::with_source(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),stock(),reserved_now,100,100000);let mut foreign=OriginalWorkFixture::with_source(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),stock(),reserved_now,100,100000);let job=65571;let mut admission=Some(super::super::OriginalJobAdmission{job,kind:FRAMEWORK_RESERVED_JOB_KIND.into(),input:Some(vec![81;65]),checkpoint:None});
 let((admitted,progress),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|{let before=cx.retained_progress();let admitted=semio_framework_async::poll::resolve_ready(super::super::start_job(&mut admission,cx))?;Ok((admitted,difference(cx.retained_progress(),before)))}).unwrap());assert!(admitted&&admission.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));let mut provider=super::super::RegisteredOriginalActorJobs::borrow_original(71,3);
 RESERVED_CLOCK.with(|clock|clock.set(101));let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.work_turn(grant(),1,|cx|{assert!(super::super::job_admission_demands(job,cx).is_err());assert!(provider.cancel(job,cx).is_err());assert!(provider.step(job,cx).is_err());assert!(provider.close(job,cx).is_err());Ok(())}).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(super::super::original_job_is_cancelled(job),Some(false));foreign.finish();
 let mut closed=false;for _ in 0..10000{let((done,progress),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|{assert!(cx.should_yield());let before=cx.retained_progress();let done=provider.close(job,cx)?;Ok((done,difference(cx.retained_progress(),before)))}).unwrap());assert!(progress.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));if done{closed=true;break}}
 assert!(closed);assert!(!super::super::has_owned_jobs(71,3));assert_eq!(reserved_now(),Some(101));owner.finish();assert_eq!(reserved_now(),Some(101));
}

#[test]
fn reserved_registry_original_child_release_denial_preserves_last_work_unit(){
 let mut owner=caller();let mut source=Some(vec![81u8;65]);let mut closing=None;let mut found=false;
 for _ in 0..10000{if closing.as_ref().is_some_and(|close:&ControlledRetirement<Vec<u8>>|close.next_demand(grant().maximum_copy_bytes).unwrap().release_bytes>0){found=true;break}let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();super::super::close_original(&mut source,&mut closing,cx)?;Ok(difference(cx.retained_progress(),before))})).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}
 assert!(found);let((progress,fuel),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(RetainedCloneGrant{maximum_release_bytes:0,..grant()},1,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();assert!(!super::super::close_original(&mut source,&mut closing,cx)?);Ok((difference(cx.retained_progress(),before),cx.fuel_remaining()))})).unwrap());assert_eq!(progress,Default::default());assert_eq!(fuel,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 for _ in 0..10000{if source.is_none()&&closing.is_none(){break}let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.work_turn(grant(),1,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();super::super::close_original(&mut source,&mut closing,cx)?;Ok(difference(cx.retained_progress(),before))})).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}assert!(source.is_none()&&closing.is_none());owner.finish();
}
